import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), k = nextInt();
        long[] a = new long[n], gain = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        long total = 0;
        for (int i = 0; i < n; i++) {
            long b = nextLong();
            total += b; // start with every task given to the second person
            gain[i] = a[i] - b;
        }
        Arrays.sort(gain);
        for (int i = 0; i < k; i++) total += gain[n - 1 - i];
        System.out.println(total);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := int(nextInt()), int(nextInt())
	a := make([]int64, n)
	gain := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	var total int64
	for i := 0; i < n; i++ {
		b := nextInt()
		total += b // start with every task given to the second person
		gain[i] = a[i] - b
	}
	sort.Slice(gain, func(i, j int) bool { return gain[i] > gain[j] })
	for i := 0; i < k; i++ {
		total += gain[i]
	}
	fmt.Println(total)
}
